func TestAutoSaveRepository_HasAutoSave(t *testing.T) {
	tmpDir := t.TempDir()
	db, err := NewDatabase(filepath.Join(tmpDir, "test.db"))
	if err != nil {
		t.Fatalf("NewDatabase() error = %v", err)
	}
	defer db.Close()

	repo := db.AutoSaveRepo()

	has, err := repo.HasAutoSave(1)
	if err != nil {
